use vstd::prelude::*;

verus! {
    /// Compute the minimum number of inspectors needed to cover `n` items
    /// when each inspector has symmetric coverage radius `d`.
    ///
    /// Each inspector covers a contiguous block of length `2*d + 1`,
    /// and we need to cover all `n` items.  The answer is
    /// ceil(n / (2*d + 1)), which for positive integers is
    /// (n + (2*d + 1) - 1) / (2*d + 1) = (n + 2*d) / (2*d + 1).
    fn min_inspectors(n: i8, d: i8) -> (result: i8)
        requires
            1 <= n && n <= 20,
            1 <= d && d <= 20,
        ensures
            // The returned result indeed matches the ceiling formula
            result == (n + 2*d) / (2*d + 1),
            // And in particular it covers all n items
            result * (2*d + 1) >= n,
            // But if we used one fewer inspector, we'd miss at least one item
            (result - 1) * (2*d + 1) < n,
            // Finally, the result is between 1 and n
            1 <= result && result <= n,
    {
        // Width of coverage for one inspector
        let width: i8 = 2 * d + 1;
        // Compute the ceiling of n / width via the standard integer formula
        // Since n ≥ 1 and width ≥ 3, the numerator is ≥ width,
        // so (n + width - 1) / width ≥ 1.
        let numerator: i8 = n + width - 1;
        // Integer division on positive operands gives floor,
        // so this implements ceil(n / width).
        return numerator / width;
    }
}

